+    public int testLongSubOneLE(long x) {
+        return Long.compareUnsigned(x - 1, x) <= 0 ? TRUE_RESULT : FALSE_RESULT;
+    }
+
+    @Test
+    @IR(failOn = {CMP_UL, ADD_L, SUB_L})
+    @IR(counts = {CMP_L, "1"})
+    public int testLongSubOneGT(long x) {
+        return Long.compareUnsigned(x - 1, x) > 0 ? TRUE_RESULT : FALSE_RESULT;
+    }
+
@@ -262,1 +296,1 @@
